CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, email TEXT UNIQUE NOT NULL, username TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'user', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS documents (id BIGSERIAL PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', content TEXT NOT NULL, required_level INT NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'published', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE documents ADD COLUMN IF NOT EXISTS rsvp_level INT;
ALTER TABLE documents ADD COLUMN IF NOT EXISTS wpm INT NOT NULL DEFAULT 300;
UPDATE documents SET rsvp_level=required_level WHERE rsvp_level IS NULL;
ALTER TABLE documents ALTER COLUMN rsvp_level SET DEFAULT 1;
CREATE TABLE IF NOT EXISTS questions (id BIGSERIAL PRIMARY KEY, document_id BIGINT REFERENCES documents(id) ON DELETE CASCADE, question_text TEXT NOT NULL, option_a TEXT NOT NULL, option_b TEXT NOT NULL, option_c TEXT NOT NULL, option_d TEXT NOT NULL, correct_option CHAR(1) NOT NULL, order_index INT NOT NULL DEFAULT 0);
ALTER TABLE questions ADD COLUMN IF NOT EXISTS question_type TEXT NOT NULL DEFAULT 'multiple_choice';
ALTER TABLE questions ALTER COLUMN correct_option TYPE TEXT;
CREATE TABLE IF NOT EXISTS reading_sessions (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES users(id) ON DELETE CASCADE, document_id BIGINT REFERENCES documents(id) ON DELETE CASCADE, rsvp_level INT NOT NULL, wpm INT NOT NULL, status TEXT NOT NULL DEFAULT 'reading', started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), completed_at TIMESTAMPTZ, reading_duration_ms INT DEFAULT 0, current_chunk INT DEFAULT 0, score NUMERIC(5,2), passed BOOLEAN);
CREATE TABLE IF NOT EXISTS answers (id BIGSERIAL PRIMARY KEY, session_id BIGINT REFERENCES reading_sessions(id) ON DELETE CASCADE, question_id BIGINT REFERENCES questions(id) ON DELETE CASCADE, selected_option CHAR(1) NOT NULL, is_correct BOOLEAN NOT NULL, response_time_ms INT DEFAULT 0, UNIQUE(session_id, question_id));
ALTER TABLE answers ALTER COLUMN selected_option TYPE TEXT;
CREATE TABLE IF NOT EXISTS level_settings (level INT PRIMARY KEY CHECK(level BETWEEN 1 AND 4), wpm INT NOT NULL DEFAULT 300, promotion_correct_answers INT, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE level_settings ADD COLUMN IF NOT EXISTS wpm INT NOT NULL DEFAULT 300;
INSERT INTO level_settings(level,wpm,promotion_correct_answers) VALUES (1,250,NULL),(2,300,7),(3,350,7),(4,400,NULL) ON CONFLICT(level) DO NOTHING;
