INSERT INTO documents(title,description,content,required_level,status) VALUES ('Tập trung để hiểu','Cách giữ sự chú ý khi đọc một bài khó.','Đọc sâu bắt đầu từ việc chọn một mục tiêu rõ ràng. Khi đọc, em hãy gạch chân ý chính, tự hỏi vì sao tác giả viết điều này và nối mỗi đoạn với điều em đã biết. Sự tập trung không phải tài năng bẩm sinh; đó là thói quen có thể luyện mỗi ngày.',1,'published'),('Đọc lại để nhớ lâu','Vì sao lần đọc thứ hai giúp kiến thức bền hơn.','Lần đọc đầu giúp em nhìn thấy bản đồ của văn bản. Lần đọc thứ hai giúp em hiểu địa hình. Khi đọc lại với một câu hỏi cụ thể, những đoạn quen thuộc sẽ hé lộ cấu trúc, dẫn chứng và mối liên hệ mới.',2,'published'),('Xây thói quen học tập','Thiết kế một hệ thống học tập phù hợp với ngày bận rộn.','Một hệ thống nhỏ thường bền vững vì nó yêu cầu ít hơn. Hãy đặt sách ở nơi dễ thấy, chia nhiệm vụ thành bước ngắn và ghi lại một điều em hiểu sau mỗi lần đọc. Tiến bộ đến từ môi trường hỗ trợ, không chỉ từ ý chí.',3,'published'),('Suy nghĩ có chiều sâu','Bài đọc rèn khả năng phân tích và lập luận.','Tập trung là nghệ thuật loại bỏ điều thừa. Đóng những tab không cần thiết, đặt điện thoại ra xa và dành một khoảng thời gian yên tĩnh cho câu hỏi khó. Khi đọc xong, hãy giải thích lại bằng lời của em và tìm bằng chứng trong văn bản.',4,'published') ON CONFLICT DO NOTHING;
INSERT INTO questions(document_id,question_text,option_a,option_b,option_c,option_d,correct_option,order_index) SELECT id,'Đọc sâu bắt đầu từ điều gì?','Đọc thật nhanh','Chọn mục tiêu rõ ràng','Đọc không cần nghỉ','Học thuộc mọi câu','b',1 FROM documents WHERE title='Tập trung để hiểu' AND NOT EXISTS (SELECT 1 FROM questions);
